/// Length of each array-of-structures level along `code_library`.
fn lengths_code_library(tf: &Tf, level: usize, _at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(tf.code.library.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `coil`.
fn lengths_coil(tf: &Tf, level: usize, _at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(tf.coil.len()),
        _ => return None,
    }
}

/// Length of each array-of-structures level along `coil_conductor`.
fn lengths_coil_conductor(tf: &Tf, level: usize, at: &[usize]) -> Option<usize> {
    match level {
        0 => return Some(tf.coil.len()),
        1 => return Some(tf.coil.get(at[0])?.conductor.len()),
        _ => return None,
    }
}

